#!/usr/bin/env swift
//
// Builds Screvia.xcodeproj and copies the result to .build/Screvia.app.
//
//   swift scripts/BuildApp.swift [--no-open] [--sign <identity>]
//
// Screvia.xcodeproj is generated by XcodeGen from project.yml and is
// gitignored, so this always regenerates it first. Everything else —
// bundling resources, embedding the LicenseList/KeyboardShortcuts plugin
// output, codesigning — is xcodebuild's job now; SwiftPM only builds the
// ScreviaKit library.

import Foundation

struct CommandError: LocalizedError {
    let command: String
    let status: Int32
    var errorDescription: String? { "\(command) exited with status \(status)" }
}

@discardableResult
func run(
    _ launchPath: String,
    _ arguments: [String],
    environment: [String: String]? = nil,
    captureOutput: Bool = false
) throws -> String {
    let process = Process()
    process.executableURL = URL(fileURLWithPath: launchPath)
    process.arguments = arguments
    if let environment {
        process.environment = ProcessInfo.processInfo.environment.merging(environment) { _, new in new }
    }

    let pipe = Pipe()
    if captureOutput {
        process.standardOutput = pipe
    }

    try process.run()
    // Read before waiting: a full pipe buffer would deadlock the child.
    let data = captureOutput ? pipe.fileHandleForReading.readDataToEndOfFile() : Data()
    process.waitUntilExit()

    guard process.terminationStatus == 0 else {
        throw CommandError(
            command: ([launchPath] + arguments).joined(separator: " "),
            status: process.terminationStatus
        )
    }

    return String(data: data, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
}

let fm = FileManager.default

// MARK: - Arguments

var shouldOpen = true
var signingIdentity = "-"

var arguments = Array(CommandLine.arguments.dropFirst())
while let argument = arguments.first {
    arguments.removeFirst()
    switch argument {
    case "--no-open":
        shouldOpen = false
    case "--sign":
        guard let identity = arguments.first else {
            FileHandle.standardError.write(Data("--sign needs an identity\n".utf8))
            exit(2)
        }
        arguments.removeFirst()
        signingIdentity = identity
    default:
        FileHandle.standardError.write(Data("unknown argument: \(argument)\n".utf8))
        exit(2)
    }
}

// MARK: - Layout

let repoRoot = URL(fileURLWithPath: #filePath)
    .deletingLastPathComponent()
    .deletingLastPathComponent()
let buildRoot = repoRoot.appending(path: ".build")
let derivedDataDir = buildRoot.appending(path: "DerivedData")
let appDir = buildRoot.appending(path: "Screvia.app")

// LicenseList's build plugin looks for Xcode's SourcePackages layout, which
// a custom -derivedDataPath still provides — xcodebuild always writes it,
// unlike the SwiftPM CLI.
let buildEnvironment = ["PLL_SOURCE_PACKAGES_PATH": derivedDataDir.appending(path: "SourcePackages").path]

do {
    try run("/opt/homebrew/bin/xcodegen", ["generate"], environment: buildEnvironment)

    try run(
        "/usr/bin/xcodebuild",
        [
            "-project", "Screvia.xcodeproj",
            "-scheme", "Screvia",
            "-configuration", "Release",
            "-derivedDataPath", derivedDataDir.path,
            "-skipPackagePluginValidation",
            "CODE_SIGN_IDENTITY=\(signingIdentity)",
            "build"
        ],
        environment: buildEnvironment
    )

    let builtApp = derivedDataDir.appending(path: "Build/Products/Release/Screvia.app")
    if fm.fileExists(atPath: appDir.path) {
        try fm.removeItem(at: appDir)
    }
    try run("/usr/bin/ditto", [builtApp.path, appDir.path])

    print("Built \(appDir.path)")

    if shouldOpen {
        try run("/usr/bin/open", [appDir.path])
    }
} catch {
    FileHandle.standardError.write(Data("error: \(error.localizedDescription)\n".utf8))
    exit(1)
}
